viewof torbu = Inputs.range([1, 14], {value: 9,step: 0.1,label: "Torrsubstans (%)"})
viewof kvare = Inputs.range([0, 100], {value: 5,step: 0.1,label: "Kväve (g/L)"})

html`&lt;div&gt;
  &lt;h4&gt;Behandling:&lt;/h4&gt;
&lt;/div&gt;`
viewof klosevatten = Inputs.range([0, 1500], {value: 10,step: 0.1,label: "Klosettvatten (m3)"})
viewof urea = Inputs.range([0, 100], {value: 1000,step: 0.1,label: "Urea-dos (kg/m3)"})

html`&lt;div&gt;
  &lt;h4&gt;Gödsling:&lt;/h4&gt;
&lt;/div&gt;`
viewof totalkvave = Inputs.range([0, 160], {value: 60,step: 0.1,label: "Totalkväve (kg/ha)"})
totalkvave_f = 0.17
  ammonia_f = 0.14
  fosfor_f = 0.019
  kalium_f = 0.045
  svavel_f = 0.11

  totalkvave_k = torbu*10*totalkvave_f+urea*0.46
  ammonia_k = torbu*10*ammonia_f+urea*0.46
  fosfor_k = torbu*10*fosfor_f
  kalium_k = torbu*10*kalium_f
  svavel_k = torbu*10*svavel_f

  giva = totalkvave/totalkvave_k
  Spridningsareal = klosevatten/giva

  totalkvave_g = 100
  ammonia_g = giva*ammonia_f+urea*0.46
  fosfor_g = giva*fosfor_f
  kalium_g = giva*kalium_f
  svavel_g = giva*svavel_f

