  {Näringsämne: "Fosfor", "Koncentration(kg/ton)": fosfor_k, "Giva(kg/ha)":fosfor_g},
  {Näringsämne: "Kalium", "Koncentration(kg/ton)": kalium_k, "Giva(kg/ha)":kalium_g},
  {Näringsämne: "Svavel","Koncentration(kg/ton)": svavel_k, "Giva(kg/ha)":svavel_g},
]

Inputs.table(data, {select: false});
