Ammonia kalkylator




html`&lt;div&gt;
  &lt;h4&gt;&lt;strong&gt;Rötrestens egenskaper:&lt;/strong&gt;&lt;/h4&gt;
&lt;/div&gt;`
viewof pH = Inputs.range([1, 14], {value: 9,step: 0.1,label: "pH"})
viewof dry = Inputs.range([0, 100], {value: 5,step: 0.1,label: "Torrsubstans (g/L)"})
viewof temp = Inputs.range([0, 50], {value: 10,step: 0.1,label: "Lagrings temperatur (°C)"})

html`&lt;div&gt;
  &lt;h4&gt;Behandlingens egenskaper:&lt;/h4&gt;
&lt;/div&gt;`
viewof urea = Inputs.range([0, 100], {value: 10,step: 0.1,label: "Tillsatt urea (kg/m³)"})
viewof va_vol = Inputs.range([0, 10000], {value: 1000,step: 0.1,label: "VA-volym (m³)"})

html`&lt;div&gt;
  &lt;h4&gt;Målapplikation:&lt;/h4&gt;
&lt;/div&gt;`
viewof n_target = Inputs.range([0, 100], {value: 60,step: 0.1,label: "Kvävemål (kg/ha)"})
pKa = (2729.92 / (temp + 273.15)) + 0.090181
  f_nh3 = 1 / (10 ** (pKa - pH) + 1)
  TAN = (dry * 0.145) + (urea * 0.466)
  NH3aq = TAN * f_nh3
  duration = -5 / (-0.8 * ((NH3aq / 14.01) * 1000) * 0.0037 * Math.exp(0.066 * temp))
  C_n = dry * 0.171 + urea * 0.466
  application = n_target / C_n
  land = va_vol / application

